content.text:
The evidence points to one fault at ts-seat-service, which I have named as a network delay on its connection to ts-order-other-service, with the propagation running through travel2, route-plan and travel-plan to the dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "network_delay",
      "evidence": [
        {"kind": "trace", "sql": "WITH c AS (SELECT trace_id, span_id, duration::DOUBLE d FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Client' AND span_name='POST') SELECT ch.service_name, count(*) n, round(approx_quantile(c.d/1e6,0.5),1) client_ms_p50, round(approx_quantile(ch.duration/1e6,0.5),1) server_ms_p50 FROM c JOIN abnormal_traces ch ON ch.trace_id=c.trace_id AND ch.parent_span_id=c.span_id GROUP BY 1", "claim": "Seat POST calls to ts-order-other take ~1277ms at p50 while order-other server spans take ~3ms; ts-order-service calls stay ~5ms."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration/1e6,0.5),1) p50_ms, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Internal' GROUP BY 1,2", "claim": "ts-seat-service SeatController.getLeftTicketOfInterval p95 rises to ~2074ms while its CPU and memory stay normal."},
        {"kind": "metric", "sql": "SELECT attr_source, attr_destination, metric, round(avg(value),1) avg_v, count(*) n FROM abnormal_metrics_sum WHERE metric='hubble_flows_processed_total' AND attr_source LIKE '%ts-seat-service%' AND attr_destination LIKE '%ts-order-other-service%' GROUP BY 1,2,3", "claim": "Hubble flow counts on the seat to order-other connection are present and rise to ~2294 per sample, with no drops recorded."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-seat-service", "to": "ts-travel2-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Server' GROUP BY 1,2,3", "claim": "ts-travel2-service server spans, including trips/left, slow to ~5.9s p95 while calling the delayed seat service."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Server' GROUP BY 1,2,3", "claim": "ts-route-plan-service server spans rise to ~6.5s p95 while waiting on travel2 calls."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY 1,2,3", "claim": "ts-travel-plan-service server spans rise to ~12.7s p95, far above its normal ~726ms."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' GROUP BY 1,2,3", "claim": "ts-ui-dashboard user-facing server spans rise to ~2.0s p95 from ~161ms, with no error status increase."}]}
  ]
}
```
